const p=$input.first().json;
if(p.approvedForOnePaidRequest!==true) throw new Error('Review the estimate and approve one paid request in Edit product brief.');
if(typeof p.sku!=='string'||!p.sku.trim()) throw new Error('Provide a SKU for your review record.');
if(typeof p.imageUrl!=='string'||!/^https:\/\/[A-Za-z0-9.-]+(?::443)?\/[^\s#]*$/.test(p.imageUrl)||/^https:\/\/example\.com(?:[:/]|$)/i.test(p.imageUrl)) throw new Error('Replace the placeholder with a permitted public HTTPS reference.');
if(typeof p.prompt!=='string'||!p.prompt.trim()||p.prompt.length>5000) throw new Error('Provide a prompt of 1..5000 characters.');
return [{json:{sku:p.sku,request:{imageUrls:[p.imageUrl],prompt:p.prompt,outputNum:1,resolution:'1K',aspectRatio:'1:1'}}}];

const raw=$input.first().json;
const d=raw.data;
if(raw.code!==0||!d||!['PENDING','RUNNING','SUCCEEDED','FAILED','TIMEOUT'].includes(d.status)||typeof d.taskId!=='string'||! /^[A-Za-z0-9_-]{8,128}$/.test(d.taskId)) throw new Error('Unaccepted or unexpected task receipt; inspect the saved execution before retrying.');
const source=$('Validate product request').first().json;
return [{json:{sku:source.sku,request:source.request,taskId:d.taskId,submitResponse:raw}}];

const raw=$input.first().json;
const saved=$('Save task receipt').first().json;
const d=raw.data;
const attempt=$runIndex+1;
if(raw.code!==0||!d||d.taskId!==saved.taskId||!['PENDING','RUNNING','SUCCEEDED','FAILED','TIMEOUT'].includes(d.status)) throw new Error('Unexpected task response or mismatched task ID; do not resubmit generation.');
if(d.status==='SUCCEEDED'&&(!d.result||typeof d.result!=='object'||Array.isArray(d.result))) throw new Error('Unexpected completed result; inspect the raw response.');
const pending=['PENDING','RUNNING'].includes(d.status);
return [{json:{...saved,queryResponse:raw,status:d.status,queryAttempt:attempt,continuePolling:pending&&attempt<6,decision:d.status==='SUCCEEDED'?'needs_human_review':pending?(attempt<6?'polling':'poll_limit_reached'):'inspect_failure'}}];
